/**
 * Writes scripts/data/uae-drug-pricing-ede-takeover-launch-research.json with every Sanity
 * blogPost field filled from the hardcoded SSR module.
 *
 * Cover / hero JPEGs are generated by scripts/generate-uae-ede-launch-research-cover.mjs.
 *
 *   node scripts/generate-uae-ede-launch-research-sanity-json.mjs
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { createServer } from 'vite';

const root = path.join(path.dirname(fileURLToPath(import.meta.url)), '..');
const outPath = path.join(root, 'scripts/data/uae-drug-pricing-ede-takeover-launch-research.json');

export const MARTHA_DEVITO_SANITY_ID = '6263dcc8-994f-4cd1-9228-7e92332659d3';

/** Every blogPost field that applies to a healthcare-silo article. */
export const UAE_EDE_SANITY_FIELDS = [
  'seo',
  'openGraph',
  'title',
  'slug',
  'excerpt',
  'publishedAt',
  'updatedAt',
  'author',
  'mainImage',
  'categories',
  'category',
  'contentSilo',
  'tags',
  'country',
  'language',
  'readingTime',
  'executiveSummary',
  'tableOfContents',
  'bodyHtml',
  'body',
  'faq',
  'relatedPostSlugs',
  'ctaSection',
  'sources',
  'factCheckedAt',
];

function stripHtml(html) {
  return String(html)
    .replace(/<[^>]+>/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&#x27;|&#39;/g, "'")
    .replace(/&quot;/g, '"')
    .replace(/&nbsp;/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function portableText(text) {
  return {
    _type: 'block',
    style: 'normal',
    children: [{ _type: 'span', marks: [], text }],
    markDefs: [],
  };
}

function extractSources(bodyHtml) {
  return [...bodyHtml.matchAll(/<li id="ref-[^"]+">([\s\S]*?)<\/li>/g)].map((match) =>
    stripHtml(match[1]),
  );
}

async function loadArticle() {
  const vite = await createServer({
    root,
    server: { middlewareMode: true },
    appType: 'custom',
    logLevel: 'error',
  });
  try {
    return await vite.ssrLoadModule('/src/data/blog-uae-drug-pricing-ede-takeover-launch-research.ts');
  } finally {
    await vite.close();
  }
}

export function buildSanityPayload(mod) {
  const shortAnswer = stripHtml(mod.UAE_EDE_EXECUTIVE_SUMMARY_HTML).replace(
    /^Short answer:\s*/i,
    '',
  );
  const firstParagraph = stripHtml(mod.UAE_EDE_BODY_HTML.split('<h2')[0])
    .replace(/^UAE drug pricing[\s\S]*?This briefing uses only published sources\./, '')
    .trim();

  return {
    seo: {
      metaTitle: mod.UAE_EDE_META_TITLE,
      metaDescription: mod.UAE_EDE_META_DESCRIPTION,
      focusKeyword: 'UAE drug pricing',
      keywords: [
        'UAE drug pricing',
        'Emirates Drug Establishment',
        'UAE launch research',
        'UAE launch research 2026',
        'EDE Decision 12 2026',
        'UAE medicine price cut',
        'UAE drug re-pricing',
        'UAE market access research',
      ],
      canonicalUrl: mod.UAE_EDE_URL,
      noIndex: false,
    },
    openGraph: {
      ogTitle: mod.UAE_EDE_META_TITLE,
      ogDescription: mod.UAE_EDE_META_DESCRIPTION,
      ogImage: {
        path: `public${mod.UAE_EDE_COVER_IMAGE}`,
        alt: mod.UAE_EDE_COVER_IMAGE_ALT,
        geminiPending: false,
      },
    },
    title: mod.UAE_EDE_DISPLAY_TITLE,
    slug: { _type: 'slug', current: mod.UAE_EDE_SLUG },
    excerpt: mod.UAE_EDE_EXCERPT,
    publishedAt: mod.UAE_EDE_PUBLISHED_ISO,
    updatedAt: mod.UAE_EDE_UPDATED_ISO,
    author: {
      _type: 'reference',
      _ref: MARTHA_DEVITO_SANITY_ID,
      name: 'Martha DeVito',
      jobTitle: 'Global Research Manager',
    },
    mainImage: {
      path: `public${mod.UAE_EDE_HERO_IMAGE}`,
      alt: mod.UAE_EDE_HERO_IMAGE_ALT,
      caption: 'BioNixus-branded hero for UAE drug pricing after the EDE takeover',
      geminiPending: false,
    },
    categories: [{ title: 'Healthcare Market Research' }],
    category: 'Healthcare Market Research',
    contentSilo: 'healthcare',
    tags: [...mod.UAE_EDE_TAGS],
    country: 'United Arab Emirates',
    language: 'en',
    readingTime: mod.UAE_EDE_READING_TIME,
    executiveSummary: [portableText(shortAnswer)],
    tableOfContents: mod.UAE_EDE_TABLE_OF_CONTENTS.map((item) => ({
      heading: item.heading,
      anchor: item.anchor,
    })),
    bodyHtml: `${mod.UAE_EDE_EXECUTIVE_SUMMARY_HTML}\n\n${mod.UAE_EDE_BODY_HTML}`,
    body: [
      {
        _type: 'callout',
        type: 'insight',
        title: 'Short answer',
        content: shortAnswer,
      },
      {
        _type: 'dataVisualization',
        title: 'What UAE launch research should measure after EDE',
        type: 'table',
        data: JSON.stringify(
          mod.UAE_EDE_WORKSTREAMS.map((stream) => ({
            name: stream.name,
            researchType: stream.researchType,
            question: stream.question,
          })),
        ),
        source: 'MOHAP 5 January 2026; Gulf News 26 May 2026; WAM 22 September 2026; Decree-Law 38/2024',
      },
      portableText(
        firstParagraph ||
          'UAE drug pricing is a research problem again, not only a regulatory filing.',
      ),
    ],
    faq: mod.UAE_EDE_FAQ.map((item) => ({
      question: item.question,
      answer: item.answer,
    })),
    relatedPostSlugs: ['market-access-strategy-uae', 'gcc-pharmacoeconomics', 'uae-healthcare-market-trends-2026'],
    ctaSection: { ...mod.UAE_EDE_HARDCODED_POST.ctaSection },
    sources: extractSources(mod.UAE_EDE_BODY_HTML),
    factCheckedAt: mod.UAE_EDE_UPDATED_ISO,
    geminiCoverPending: false,
    coverNote:
      'mainImage and openGraph.ogImage are the Playwright-rendered BioNixus JPEGs at public/images/blog/uae-drug-pricing-ede-takeover-launch-research-{hero,cover}.jpg.',
  };
}

async function main() {
  const mod = await loadArticle();
  const payload = buildSanityPayload(mod);
  for (const field of UAE_EDE_SANITY_FIELDS) {
    if (payload[field] == null) {
      throw new Error(`Sanity payload missing field: ${field}`);
    }
  }
  fs.mkdirSync(path.dirname(outPath), { recursive: true });
  fs.writeFileSync(outPath, `${JSON.stringify(payload, null, 2)}\n`);
  console.log(`Wrote ${path.relative(root, outPath)} (${payload.sources.length} sources, bodyHtml ${payload.bodyHtml.length} chars)`);
}

if (process.argv[1] && fileURLToPath(import.meta.url) === path.resolve(process.argv[1])) {
  main().catch((error) => {
    console.error(error);
    process.exit(1);
  });
}
